#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define STORE_PATH "/var/lib/secstore/"
#define KEY_LEN 32
#define IV_LEN 16
#define TAG_LEN 16
#define MAX_RECORD_SIZE 4096

typedef struct {
    uint32_t version;
    uint32_t record_id;
    uint32_t payload_len;
    uint8_t  flags;
    uint8_t  reserved[3];
} __attribute__((packed)) record_header_t;

typedef struct {
    uint8_t iv[IV_LEN];
    uint8_t tag[TAG_LEN];
    uint8_t ciphertext[];
} __attribute__((packed)) encrypted_blob_t;

typedef struct {
    pthread_mutex_t lock;
    uint8_t master_key[KEY_LEN];
    char store_dir[256];
    uint32_t next_id;
} secure_store_t;

static int derive_record_key(const uint8_t *master, uint32_t record_id,
                             uint8_t *out_key) {
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    if (!ctx) return -1;
    uint8_t salt[8];
    memcpy(salt, &record_id, 4);
    memset(salt + 4, 0x5a, 4);
    unsigned int len = KEY_LEN;
    int ok = 1;
    ok &= EVP_DigestInit_ex(ctx, EVP_sha256(), NULL);
    ok &= EVP_DigestUpdate(ctx, master, KEY_LEN);
    ok &= EVP_DigestUpdate(ctx, salt, 8);
    ok &= EVP_DigestFinal_ex(ctx, out_key, &len);
    EVP_MD_CTX_free(ctx);
    return ok ? 0 : -1;
}

static int encrypt_record(const uint8_t *key, const uint8_t *plaintext,
                          size_t pt_len, encrypted_blob_t *blob) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;
    int outlen = 0, tmplen = 0;
    if (RAND_bytes(blob->iv, IV_LEN) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, blob->iv) != 1 ||
        EVP_EncryptUpdate(ctx, blob->ciphertext, &outlen, plaintext, (int)pt_len) != 1 ||
        EVP_EncryptFinal_ex(ctx, blob->ciphertext + outlen, &tmplen) != 1 ||
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, TAG_LEN, blob->tag) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    EVP_CIPHER_CTX_free(ctx);
    return outlen + tmplen;
}

static int serialize_and_store(secure_store_t *store, const void *data,
                               size_t data_len, uint32_t *out_id) {
    if (data_len > MAX_RECORD_SIZE - sizeof(record_header_t))
        return -1;

    uint32_t assigned_id;
    char filepath[512];
    uint8_t record_key[KEY_LEN];
    uint8_t buffer[MAX_RECORD_SIZE + sizeof(encrypted_blob_t) + 256];

    /* Entire operation is atomic under the lock */
    pthread_mutex_lock(&store->lock);
    assigned_id = store->next_id++;

    /* Build the serialized record */
    record_header_t hdr;
    hdr.version = 1;
    hdr.record_id = assigned_id;
    hdr.payload_len = (uint32_t)data_len;
    hdr.flags = 0;
    memset(hdr.reserved, 0, 3);

    uint8_t plaintext[MAX_RECORD_SIZE];
    memcpy(plaintext, &hdr, sizeof(hdr));
    memcpy(plaintext + sizeof(hdr), data, data_len);
    size_t total_pt = sizeof(hdr) + data_len;

    /* Derive key and encrypt */
    if (derive_record_key(store->master_key, assigned_id, record_key) != 0) {
        memset(record_key, 0, KEY_LEN);
        memset(plaintext, 0, sizeof(plaintext));
        store->next_id--;
        pthread_mutex_unlock(&store->lock);
        return -1;
    }
    encrypted_blob_t *blob = (encrypted_blob_t *)buffer;
    int ct_len = encrypt_record(record_key, plaintext, total_pt, blob);
    if (ct_len < 0) {
        memset(record_key, 0, KEY_LEN);
        memset(plaintext, 0, sizeof(plaintext));
        store->next_id--;
        pthread_mutex_unlock(&store->lock);
        return -1;
    }

    /* Write to storage atomically with O_CREAT|O_EXCL */
    snprintf(filepath, sizeof(filepath), "%s/rec_%08x.enc",
             store->store_dir, assigned_id);

    int fd = open(filepath, O_WRONLY | O_CREAT | O_EXCL, 0600);
    if (fd < 0) {
        memset(record_key, 0, KEY_LEN);
        memset(plaintext, 0, sizeof(plaintext));
        store->next_id--;  /* rollback */
        pthread_mutex_unlock(&store->lock);
        return -1;
    }

    size_t blob_size = sizeof(encrypted_blob_t) + ct_len;
    ssize_t written = write(fd, blob, blob_size);
    if (written != (ssize_t)blob_size) {
        close(fd);
        unlink(filepath);
        memset(record_key, 0, KEY_LEN);
        memset(plaintext, 0, sizeof(plaintext));
        store->next_id--;
        pthread_mutex_unlock(&store->lock);
        return -1;
    }
    fsync(fd);
    close(fd);

    pthread_mutex_unlock(&store->lock);

    memset(record_key, 0, KEY_LEN);
    memset(plaintext, 0, sizeof(plaintext));

    *out_id = assigned_id;
    return 0;
}

static int read_and_deserialize(secure_store_t *store, uint32_t record_id,
                                void *out_data, size_t *out_len) {
    char filepath[512];
    uint8_t record_key[KEY_LEN];
    uint8_t file_buf[MAX_RECORD_SIZE + sizeof(encrypted_blob_t) + 256];

    snprintf(filepath, sizeof(filepath), "%s/rec_%08x.enc",
             store->store_dir, record_id);

    pthread_mutex_lock(&store->lock);
    int fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        pthread_mutex_unlock(&store->lock);
        return -1;
    }

    ssize_t nread = read(fd, file_buf, sizeof(file_buf));
    close(fd);
    pthread_mutex_unlock(&store->lock);

    if (nread < (ssize_t)sizeof(encrypted_blob_t)) return -1;

    if (derive_record_key(store->master_key, record_id, record_key) != 0) {
        memset(record_key, 0, KEY_LEN);
        return -1;
    }

    encrypted_blob_t *blob = (encrypted_blob_t *)file_buf;
    size_t ct_len = nread - sizeof(encrypted_blob_t);
    if (ct_len > MAX_RECORD_SIZE) {
        memset(record_key, 0, KEY_LEN);
        return -1;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        memset(record_key, 0, KEY_LEN);
        return -1;
    }
    uint8_t plaintext[MAX_RECORD_SIZE];
    int outlen = 0, tmplen = 0;

    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, record_key, blob->iv) != 1 ||
        EVP_DecryptUpdate(ctx, plaintext, &outlen, blob->ciphertext, (int)ct_len) != 1 ||
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, TAG_LEN, blob->tag) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        memset(record_key, 0, KEY_LEN);
        memset(plaintext, 0, sizeof(plaintext));
        return -1;
    }

    if (EVP_DecryptFinal_ex(ctx, plaintext + outlen, &tmplen) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        memset(record_key, 0, KEY_LEN);
        memset(plaintext, 0, sizeof(plaintext));
        return -1;
    }
    EVP_CIPHER_CTX_free(ctx);

    size_t decrypted_len = (size_t)(outlen + tmplen);
    if (decrypted_len < sizeof(record_header_t)) {
        memset(record_key, 0, KEY_LEN);
        memset(plaintext, 0, sizeof(plaintext));
        return -1;
    }

    record_header_t *hdr = (record_header_t *)plaintext;
    if (hdr->payload_len > MAX_RECORD_SIZE - sizeof(record_header_t)) {
        memset(record_key, 0, KEY_LEN);
        memset(plaintext, 0, sizeof(plaintext));
        return -1;
    }
    /* Ensure declared payload_len does not exceed actual decrypted bytes */
    if ((size_t)hdr->payload_len > decrypted_len - sizeof(record_header_t)) {
        memset(record_key, 0, KEY_LEN);
        memset(plaintext, 0, sizeof(plaintext));
        return -1;
    }

    memcpy(out_data, plaintext + sizeof(record_header_t), hdr->payload_len);
    *out_len = hdr->payload_len;

    memset(record_key, 0, KEY_LEN);
    memset(plaintext, 0, sizeof(plaintext));
    return 0;
}

secure_store_t *store_init(const char *dir, const uint8_t *key) {
    secure_store_t *s = calloc(1, sizeof(secure_store_t));
    if (!s) return NULL;
    if (pthread_mutex_init(&s->lock, NULL) != 0) {
        free(s);
        return NULL;
    }
    memcpy(s->master_key, key, KEY_LEN);
    strncpy(s->store_dir, dir, sizeof(s->store_dir) - 1);
    s->store_dir[sizeof(s->store_dir) - 1] = '\0';
    s->next_id = 1;
    return s;
}
